      then assign accumulatedMs := accumulatedMs + io_7;
      then if accumulatedMs >= 2000 {
        first start;
        then assign accumulatedMs := accumulatedMs - 2000;
        then assign displayNumber := (if displayNumber + 1 >= 100 ? 0 else displayNumber + 1);
      }
    }
    out attribute io_0 : Boolean = (if displayNumber - 10 * RealFunctions::floor(displayNumber / 10) <= 2 ? true else false);
