    out attribute io_3 : Integer = displayNumber;
    out attribute io_4 : Real = (if RealFunctions::floor(displayNumber / 10) <= 2 ? 30.0 else (if RealFunctions::floor(displayNumber / 10) <= 5 ? 60.0 else 90.0));
    out attribute io_5 : Real = (if RealFunctions::floor(displayNumber / 10) <= 2 ? 60.0 else (if RealFunctions::floor(displayNumber / 10) <= 5 ? 90.0 else 120.0));
    out attribute io_6 : Real = (if RealFunctions::floor(displayNumber / 10) <= 2 ? 90.0 else (if RealFunctions::floor(displayNumber / 10) <= 5 ? 120.0 else 150.0));
  }
